jQuery(document).ready(function( $ ){
	const navHeader = $('#nav-header')
	const logo = $('#nav-header .logo')
	
	// window scroll event
	$(window).scroll(function() {
		
    	if($(this).scrollTop()>= 200){
			navHeader.css('background-color','#0165A1')
			logo.css('width','125px')
    	}
		else {
			navHeader.css('background-color','#0165A100')
			logo.css('width','165px')
		}		
		
		
  });
	
	$('.hp-inner-popup-holder').on('click', function(event){
	 event.stopPropagation();
	})
	// Handle Harlow Person View Popup
	const empItems = $('.harlow-emp')
	// Open
	empItems.on('click', function(){
		$('body').css({
			'overflow-y' : 'hidden',
			'padding-right' : '20px',
		});
		$(this).find('.hp-popup-holder').fadeIn()
		$(this).find('.hp-popup-holder').css('display','flex')
// 		$(this).find('.hp-popup-inner').slideDown()
	})
	// Close
	$('.hp-popup-holder').on('click', function(event){
	    event.stopPropagation();
// 		$(this).find('.hp-popup-inner').slideUp()
		$(this).fadeOut()
		$('body').css('overflow','auto');
		$('body').css({
			'overflow-y' : 'auto',
			'padding-right' : '0',
		});
	})
	
		$('.hp-close').on('click', function(event){
		event.preventDefault();
	    event.stopPropagation();
// 		$(this).find('.hp-popup-inner').slideUp()
		$('.hp-popup-holder').fadeOut()
		$('body').css({
			'overflow-y' : 'auto',
			'padding-right' : '0',
		});
	})
	
	$('.nav-header .header-mobile-menu nav').append('<div class="close-button"></div>')
	// Close header mobile menu 
	$('.nav-header .header-mobile-menu nav .close-button').on('click', function(event){
	  $('.nav-header .header-mobile-menu .elementor-menu-toggle').removeClass('elementor-active')
	})
	
	// Handle Teams Tabs
	$('#supportive-management-btn').on('click', function(event){
		event.preventDefault();
		$('#supportive-management').removeClass('d-none')
		$('#core-management').addClass('d-none');
		$('#supportive-management-btn').addClass('active')
		$('#core-management-btn').removeClass('active')
	})
	$('#core-management-btn').on('click', function(event){
		event.preventDefault();
		$('#supportive-management').addClass('d-none')
		$('#core-management').removeClass('d-none')
		$('#supportive-management-btn').removeClass('active')
		$('#core-management-btn').addClass('active')
	})


});

